import{_ as t,o,c as a,ag as d}from"./chunks/framework.BaNuf0sO.js";const m=JSON.parse('{"title":"AppTheme（主题切换器积木）","description":"","frontmatter":{},"headers":[],"relativePath":"docs/core/src/components/app-layout/docs/README-AppTheme.md","filePath":"docs/core/src/components/app-layout/docs/README-AppTheme.md"}'),r={name:"docs/core/src/components/app-layout/docs/README-AppTheme.md"};function i(l,e,h,c,s,p){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="apptheme-主题切换器积木" tabindex="-1">AppTheme（主题切换器积木） <a class="header-anchor" href="#apptheme-主题切换器积木" aria-label="Permalink to &quot;AppTheme（主题切换器积木）&quot;">​</a></h1><blockquote><p>主题切换 UI：bridge.theme 直读直写（架构反转——真相源在 bridge，不经 app store）——亮/暗/系统三态恒显 + 风格下拉条件显示。 使用场景：AppLayout <code>#themeSwitcher</code> 内容锚默认内容；布局插件可复用作 scope.Default。</p></blockquote><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><ul><li>架构反转：主题能力在 bridge——AppTheme 经 <code>inject(APP_LAYOUT_BRIDGE_KEY)</code> 拿布局桥窄化实例，直读 bridge 主题态、直写 bridge.theme 动作；store 仅为 isDarkTheme 旧消费方转发兜底，新 UI 走 bridge 直连</li><li>亮/暗/系统三态 RadioGroup（icon + tooltip）<strong>恒显</strong>；风格下拉仅 <code>list.length &gt; 1</code> 且 <code>bridge.showThemeStyleSwitcher !== false</code> 时显示——开关只管风格切换，不影响亮暗</li><li>零 props：无对外配置项，行为全由 bridge 态决定</li></ul><h2 id="快速上手-最小可用" tabindex="-1">快速上手（最小可用） <a class="header-anchor" href="#快速上手-最小可用" aria-label="Permalink to &quot;快速上手（最小可用）&quot;">​</a></h2><p>无 props 可配，挂载即用——经 <code>#themeSwitcher</code> 锚由 shell 落位（缺省内容即内置 AppTheme，无需显式引用）：</p><ul><li>三态切换：亮色 / 暗色 / 跟随系统（icon + tooltip，恒显）</li><li>风格切换：已注册风格 &gt; 1 且 <code>showThemeStyleSwitcher !== false</code> 时显示下拉（<code>bridge.theme.labelOf(name)</code> 渲染显示名）</li></ul><h2 id="能力边界-按需使用" tabindex="-1">能力边界 / 按需使用 <a class="header-anchor" href="#能力边界-按需使用" aria-label="Permalink to &quot;能力边界 / 按需使用&quot;">​</a></h2><ul><li><strong>亮/暗/系统三态恒显</strong>：挂载即用、无任何开关——默认即够用（<code>#themeSwitcher</code> 锚缺省内容即内置 AppTheme，业务不填锚即获得）。</li><li><strong>风格下拉条件显示</strong>：仅当「已注册风格 &gt; 1 且 <code>bridge.showThemeStyleSwitcher !== false</code>」才显示——只注册一种风格时自动隐藏，无需配置；<code>showThemeStyleSwitcher</code> 只管风格切换，不影响亮暗三态。</li><li><strong>业务覆盖锚内容时需自供等效切换 UI</strong>：自供 <code>#themeSwitcher</code> 锚内容即失去默认切换器——须自供等效 UI 且走 bridge 直读直写（真相源在 bridge，[MUST NOT] 自造主题状态）。</li><li><strong>完整能力演示</strong>（自供 shell）：<code>apps/reference/src/pages/app-layout/shell/</code></li></ul><h2 id="bridge-直读直写语义" tabindex="-1">bridge 直读直写语义 <a class="header-anchor" href="#bridge-直读直写语义" aria-label="Permalink to &quot;bridge 直读直写语义&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方向</th><th>访问</th><th>语义</th></tr></thead><tbody><tr><td>读</td><td><code>bridge.themeMode.value</code></td><td>当前亮/暗/系统三态</td></tr><tr><td>读</td><td><code>bridge.themeStyle.value</code></td><td>当前风格名</td></tr><tr><td>读</td><td><code>bridge.theme.list.value</code></td><td>已注册风格名列表（length &gt; 1 才显示风格下拉）</td></tr><tr><td>读</td><td><code>bridge.showThemeStyleSwitcher</code></td><td>是否显示风格下拉（bridge init 静态选项，缺省 true；亮暗切换不受此控、恒显）</td></tr><tr><td>读</td><td><code>bridge.theme.labelOf(name)</code></td><td>风格显示名</td></tr><tr><td>写</td><td><code>bridge.theme.setMode(mode)</code></td><td>切亮/暗/系统</td></tr><tr><td>写</td><td><code>bridge.theme.setStyle(name)</code></td><td>切风格</td></tr></tbody></table><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><p>无</p><h3 id="emits" tabindex="-1">Emits <a class="header-anchor" href="#emits" aria-label="Permalink to &quot;Emits&quot;">​</a></h3><p>无</p><h3 id="slots" tabindex="-1">Slots <a class="header-anchor" href="#slots" aria-label="Permalink to &quot;Slots&quot;">​</a></h3><p>无</p><h3 id="expose" tabindex="-1">Expose <a class="header-anchor" href="#expose" aria-label="Permalink to &quot;Expose&quot;">​</a></h3><p>无</p><h2 id="反模式-注意" tabindex="-1">反模式 / 注意 <a class="header-anchor" href="#反模式-注意" aria-label="Permalink to &quot;反模式 / 注意&quot;">​</a></h2><ul><li><strong>勿绕过 bridge 自造主题状态</strong>：真相源在 bridge，切换一律 <code>bridge.theme.setMode</code> / <code>bridge.theme.setStyle</code>，[MUST NOT] 手写类名/样式副作用造成双真相</li><li>业务无视 themeSwitcher 默认内容时须自供等效切换 UI（声明驱动测试纪律）</li><li>风格下拉显隐受 <code>showThemeStyleSwitcher</code> 控制；亮暗三态不受此控、恒显</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>主题能力：<code>bridge/theme.ts</code>（createBridgeThemeHook：风格 map + setStyle/setDark + 持久化）</li><li>落位：AppShell <code>#themeSwitcher</code> 锚（scope.Default = 内置 AppTheme；业务可覆盖），AppLayout 5 内容锚之一</li><li>范式页：<code>apps/reference/src/pages/app-layout/shell/</code></li></ul>',24)])])}const b=t(r,[["render",i]]);export{m as __pageData,b as default};
